function dump(n, d=0){
  if(!n) return 'null';
  let s = ' '.repeat(d)+n.type+' | '+n.name+' | '+Math.round(n.width)+'x'+Math.round(n.height);
  if('fills' in n) s += ' | fills:'+JSON.stringify(n.fills).slice(0,200);
  if('children' in n && d<3){ for(const c of n.children) s += '\n'+dump(c,d+2); }
  return s;
}
return {workspace: ws ? {name: ws.name, children: ws.children.length, ids: ws.children.map(c=>c.id+':'+c.name)} : 'missing',
