const screens=['22:16','23:66','24:157'];
let fixed=0;
for(const id of screens){
  const scr=await figma.getNodeByIdAsync(id);
  const cards=scr.findAll(n=>n.name.startsWith('Card/'));
  for(const c of cards){
    if(Math.abs(c.width-285)>0.5){
      c.layoutSizingHorizontal='FIXED'; c.layoutSizingVertical='FIXED';
      c.resize(285,446);
      const pw=c.findOne(n=>n.name==='Photo'); if(pw){ pw.resize(285,301); const ph=pw.findOne(n=>n.name==='Product photo'); if(ph) ph.resize(285,301); }
      const ov=c.findOne(n=>n.name==='Hover overlay'); if(ov) ov.resize(285,301);
      const badge=c.findOne(n=>n.name==='Badge'); if(badge){ badge.x=285-16-48; const bt=c.findOne(n=>n.name==='Badge text'); if(bt) bt.x=badge.x; }
      fixed++;
    }
  }
}
return {fixed};

